<script setup>
import { ref, computed, watch, nextTick } from 'vue';
import Icon from './Icon.vue';
import { data, ui, dept, doctor, day, notify, confirmAction } from '../store.js';
const props=defineProps({page:String});
const query=ref('');const editor=ref(false);const editing=ref(null);const form=ref({});const error=ref('');const aiTab=ref('model');const savedAI=ref(false);const aiForm=ref({});const prompt=ref('');const resetUser=ref(null);const newPassword=ref('');const period=ref('7');const kbResults=ref(null);
const names={departments:'科室',doctors:'医生',schedules:'排班',users:'账号',kb:'知识库文档'};
const rows=computed(()=>{const src=data[props.page];return (Array.isArray(src)?src:[]).filter(r=>Object.values(r).some(v=>typeof v==='string'&&v.toLowerCase().includes(query.value.toLowerCase())));});
const stats=computed(()=>{
 const booked=data.appointments.filter(a=>a.status!=='cancelled').length;
 const total=data.schedules.reduce((n,s)=>n+s.total_num,0),remain=data.schedules.reduce((n,s)=>n+s.remain_num,0);
 return [{name:'当前挂号数',value:booked,desc:'来自演示挂号状态',icon:'calendar'}, {name:'号源使用率',value:Math.round((total-remain)/total*100)+'%',desc:'已使用 / 已放出号源',icon:'chart'}, {name:'病历锁定数',value:Object.values(data.records).filter(r=>r.status==='locked').length,desc:'仅聚合，不展示患者明细',icon:'doc'}, {name:'知识库文档',value:data.kb.length,desc:'默认关键词检索',icon:'book'}];
});
const trend=computed(()=>period.value==='7'?[28,42,36,59,48,66,51]:[20,31,39,35,55,70,61,79,63,84,77,92]);
function reload(){notify('演示数据已刷新，未请求真实服务端','info');}
function openEditor(row=null){editing.value=row;error.value='';editor.value=true;const defaults={departments:{name:'',code:'',location:'',enabled:true},doctors:{name:'',department_id:3,title:'主治医师',specialty:'',enabled:true},schedules:{doctor_id:9,department_id:3,work_date:day(1),period:'AM',total_num:20,enabled:true},users:{login_name:'',display_name:'',role:'patient',ref_id:7,password:''},kb:{title:'',category:'就诊指南',body:'',enabled:true}};form.value={...defaults[props.page],...row};}
function submit(){error.value='';const p=props.page,f=form.value,existing=editing.value;
 if(p==='departments'){
  if(!f.name?.trim()||!f.code?.trim()||!f.location?.trim())return error.value='请填写科室名称、编码和位置。';
  if(data.departments.some(r=>r!==existing&&(r.name===f.name.trim()||r.code===f.code.trim())))return error.value='BASE_NAME_TAKEN / BASE_CODE_TAKEN：名称或编码已存在。';
 } else if(p==='doctors'){
  if(!f.name?.trim()||!data.departments.some(r=>r.id===Number(f.department_id)))return error.value='请填写医生姓名并选择已有科室。';f.department_id=Number(f.department_id);
 } else if(p==='schedules'){
  const d=data.doctors.find(d=>d.id===Number(f.doctor_id));if(!d||!f.work_date||Number(f.total_num)<0||!Number.isInteger(Number(f.total_num)))return error.value='请选择医生、就诊日期，并填写非负整数总号。';f.doctor_id=d.id;f.department_id=d.department_id;f.total_num=Number(f.total_num);f.remain_num=f.total_num;
 } else if(p==='users'){
  if(!f.login_name?.trim()||!f.display_name?.trim())return error.value='请填写登录名和显示名称。';
  if(data.users.some(r=>r!==existing&&r.login_name===f.login_name))return error.value='登录名已存在。';
  if(f.role!=='admin'&&(!Number.isInteger(Number(f.ref_id))||Number(f.ref_id)<=0))return error.value='患者或医生账号必须提供正整数档案 id。';
  if(!/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[^a-zA-Z0-9]).{8,}$/.test(f.password||''))return error.value='演示口令需至少 8 位，包含大小写字母、数字与符号。';
  f.ref_id=f.role==='admin'?0:Number(f.ref_id);
 } else if(p==='kb'){
  if(!f.title?.trim()||!f.body?.trim())return error.value='请填写文档标题和正文。';if(data.kb.some(r=>r!==existing&&r.title===f.title.trim()))return error.value='文档标题已存在，不能创建矛盾副本。';
 }
 const value={...f};delete value.password;
 if(existing)Object.assign(existing,value);else{value.id=Math.max(0,...data[p].map(r=>r.id))+1;data[p].push(value);}
 form.value.password='';editor.value=false;notify(`${names[p]}演示数据已${existing?'更新':'创建'}`);kbResults.value=null;
}
function remove(row){confirmAction(`删除${names[props.page]}？`,'删除仅对当前演示数据生效。有业务引用的科室或医生不可删除。',()=>{
 if(props.page==='departments'&&(data.doctors.some(d=>d.department_id===row.id)||data.schedules.some(s=>s.department_id===row.id)))return notify('BASE_IN_USE：该科室被引用，请改为停用','error');
 if(props.page==='doctors'&&data.schedules.some(s=>s.doctor_id===row.id))return notify('BASE_IN_USE：医生有排班记录，不可删除','error');
 data[props.page]=data[props.page].filter(r=>r!==row);notify('演示记录已删除');kbResults.value=null;
 },true);}
function toggle(row){row.enabled=!row.enabled;notify(`演示记录已${row.enabled?'启用':'停用'}`);}
function exportData(){const blob=new Blob(['\uFEFF'+JSON.stringify(data[props.page]||stats.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`smart-hospital-demo-${props.page}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出虚构演示数据');}
function saveAI(){error.value='';if(aiForm.value.endpoint&&!/^https:\/\//.test(aiForm.value.endpoint))return error.value='模型端点必须使用 HTTPS。';if(aiForm.value.key_ref&&!/^(env:|file:).+/.test(aiForm.value.key_ref))return error.value='ai.key_ref 仅接受 env: / file: 引用，禁止裸密钥。';if(aiForm.value.enabled&&(!aiForm.value.endpoint||!aiForm.value.model||!aiForm.value.key_ref))return error.value='启用前需填写 HTTPS 端点、模型名与密钥引用。';if(Number(aiForm.value.timeout)<1||Number(aiForm.value.timeout)>15)return error.value='超时需在 1–15 秒之间。';Object.assign(data.ai,aiForm.value);savedAI.value=true;aiForm.value.key_ref='';notify('演示配置已保存 · 零重启界面体验，不触发真实模型');}
function savePrompt(){if(!prompt.value.includes('{complaint}')||!prompt.value.includes('{options}'))return notify('演示模板必须包含 {complaint} 和 {options} 占位符','error');data.ai.prompt=prompt.value;notify('演示 Prompt 模板已保存');}
function resetPassword(){if(!/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[^a-zA-Z0-9]).{8,}$/.test(newPassword.value))return notify('演示口令需至少 8 位并包含大小写、数字和符号','error');const u=resetUser.value;newPassword.value='';resetUser.value=null;confirmAction('确认重置演示口令？','正式重置会吊销该账号全部令牌。本页仅演示反馈，不保存口令。',()=>notify(`账号 ${u.login_name} 的演示口令已重置（口令未保存）`),true);}
function searchKb(){if(!query.value.trim())return notify('请输入检索词','error');kbResults.value=data.kb.filter(d=>d.enabled&&(d.title+d.body).includes(query.value.trim())).map(d=>({title:d.title,text:d.body.slice(0,180)}));notify(`关键词检索找到 ${kbResults.value.length} 条演示片段`,'info');}
watch(()=>props.page,()=>{query.value='';editor.value=false;error.value='';kbResults.value=null;resetUser.value=null;aiForm.value={...data.ai,key_ref:''};prompt.value=data.ai.prompt;savedAI.value=false;},{immediate:true});
// 小屏下表格改为卡片布局（styles.css @media(max-width:560px)）：把表头文字写到每个单元格的 data-label，
// 供 CSS 的 ::before 渲染成行内标签；桌面端表格不受影响。
function labelizeTables(){document.querySelectorAll('.table-card table').forEach(t=>{const heads=[...t.querySelectorAll('thead th')].map(h=>h.textContent.trim());t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{td.dataset.label=heads[i]||'';}));});}
watch([()=>props.page,rows],async()=>{await nextTick();labelizeTables();},{immediate:true});
</script>
<template>
<div v-if="page==='dashboard'"><div class="section-heading"><span class="badge">聚合数据 · 演示</span><div class="button-row"><select v-model="period" aria-label="趋势时间范围"><option value="7">近 7 日（模拟）</option><option value="30">近 30 日（模拟）</option></select><button class="button secondary" @click="reload"><Icon name="reset" :size="16"/>刷新</button></div></div><div class="stat-grid"><article v-for="s in stats" :key="s.name" class="card metric-card"><div class="metric-title"><span>{{s.name}}</span><span class="icon-tile"><Icon :name="s.icon" :size="18"/></span></div><strong>{{s.value}}</strong><p>{{s.desc}}</p></article></div><div class="grid-two space-top"><section class="card"><div class="section-heading"><h2>挂号趋势</h2><span class="small-text muted" data-reading-aid="演示">虚构示例数据</span></div><div class="chart-bars"><div v-for="(v,n) in trend" :key="n"><span class="bar-value">{{v}}</span><i :style="{height:v*1.6+'px'}"></i><span>{{n+1}}</span></div></div><div class="chart-caption" data-reading-aid="依据">图表只展示聚合趋势，不支持患者明细下钻</div></section><section class="card"><h2>科室号源使用情况</h2><div v-for="d in data.departments" :key="d.id" class="dept-progress"><div class="inline-row"><strong>{{d.name}}</strong><span class="muted">{{data.schedules.filter(s=>s.department_id===d.id).reduce((n,s)=>n+s.total_num-s.remain_num,0)}} 已使用</span></div><div class="progress-track"><i :style="{width:Math.min(100,data.schedules.filter(s=>s.department_id===d.id).reduce((n,s)=>n+s.total_num-s.remain_num,0)/Math.max(1,data.schedules.filter(s=>s.department_id===d.id).reduce((n,s)=>n+s.total_num,0))*100)+'%'}"></i></div></div></section></div><div class="grid-two space-top"><section class="card"><h2>服务状态概览</h2><div class="status-row"><span>AI 模型调用</span><span class="badge" :class="{neutral:!data.ai.enabled}">{{data.ai.enabled?'演示开关已启用':'默认关闭'}}</span></div><div class="status-row"><span>知识检索路径</span><span class="badge">关键词</span></div><div class="status-row"><span>预问诊完成</span><span class="badge">{{data.intake.complete?'1 / 1':'0 / 1'}}（演示）</span></div></section><section class="safety-card"><Icon name="shield" :size="25"/><h3>只见趋势，不见隐私</h3><p>运营接口只返回聚合计数，不提供姓名、手机号、患者或医生 id。此看板的 KPI 会随演示预约和病历操作变化。</p></section></div></div>
<div v-else-if="page==='ai'"><div class="segmented ai-tabs"><button :class="{active:aiTab==='model'}" @click="aiTab='model';error=''">模型配置</button><button :class="{active:aiTab==='prompt'}" @click="aiTab='prompt';error=''">Prompt 模板</button><button :class="{active:aiTab==='tools'}" @click="aiTab='tools';error=''">工具开关</button></div><div class="content-grid"><form v-if="aiTab==='model'" class="card" @submit.prevent="saveAI"><div class="section-heading"><h2>模型运行配置</h2><span class="badge" :class="{neutral:!data.ai.enabled}">{{data.ai.enabled?'演示已启用':'默认关闭'}}</span></div><div v-if="error" class="alert-banner danger" role="alert">{{error}}</div><label class="field">模型端点（ai.endpoint）<input v-model="aiForm.endpoint" placeholder="https://api.example.com/v1"/></label><label class="field">模型名称（ai.model）<input v-model="aiForm.model" placeholder="example-chat"/></label><label class="field">密钥引用（ai.key_ref）<input v-model="aiForm.key_ref" placeholder="env:MODEL_API_KEY 或 file:路径" autocomplete="off"/><small class="muted">已设置：{{data.ai.key_ref?'是，引用类型 '+data.ai.key_ref.split(':')[0]:'否'}}。不回显已有值，不允许填写裸密钥。</small></label><label class="field">请求超时（秒）<input v-model.number="aiForm.timeout" type="number" min="1" max="15"/></label><label class="switch-row"><span><strong>启用演示模型开关</strong><small>不会发出真实 AI 请求</small></span><input v-model="aiForm.enabled" type="checkbox" role="switch"/></label><button class="button space-top">保存演示配置</button><span v-if="savedAI" class="badge saved-badge">刚刚保存</span></form><form v-else-if="aiTab==='prompt'" class="card" @submit.prevent="savePrompt"><h2>分诊 Prompt 模板</h2><p class="muted space-top" data-reading-aid="依据">演示模板校验需保留 {complaint} 与 {options}。正式模板占位符以服务端为准。</p><label class="field">模板正文<textarea v-model="prompt" rows="12" spellcheck="false"></textarea></label><button class="button">保存模板</button></form><section v-else class="card"><h2>演示工具中心</h2><p class="muted space-top" data-reading-aid="依据">下面的键仅作界面演示；真实工具名称需从服务端读取。</p><label v-for="(enabled,key) in data.ai.tools" :key="key" class="switch-row"><span><strong>{{key}}</strong><small>独立开关 · 不调用外部服务</small></span><input v-model="data.ai.tools[key]" type="checkbox" role="switch" @change="notify('演示工具开关已更新')"/></label></section><aside class="card sticky-card"><h2>配置安全要求</h2><ul class="note-list"><li>默认不启用真实模型。</li><li>密钥必须引用环境变量或文件。</li><li>裸密钥不能提交，也不落库。</li><li>配置写入后缓存失效，无需重启。</li><li>模型输出不能改变可信号源。</li></ul><div class="alert-banner info compact"><Icon name="shield"/><p>此页面只模拟配置反馈，不出站调用模型。</p></div></aside></div></div>
<div v-else>
  <div class="section-heading"><div class="search-field"><Icon name="search" :size="17"/><input v-model="query" :placeholder="page==='users'?'按演示登录名筛选…':page==='kb'?'搜索文档或输入关键词…':`筛选${names[page]}…`" aria-label="筛选列表" @input="kbResults=null"/></div><div class="button-row"><button v-if="page==='kb'" class="button secondary" @click="searchKb">关键词检索</button><button class="button secondary export-button" @click="exportData"><Icon name="download" :size="16"/>导出演示数据</button><button class="button" @click="openEditor()"><Icon name="plus" :size="16"/>新增{{names[page]}}</button></div></div>
  <div v-if="page==='kb'" class="summary-strip"><div><strong>{{data.kb.length}}</strong><span>文档数量</span></div><div><strong>{{data.kb.reduce((n,d)=>n+Math.ceil(d.body.length/500),0)}}</strong><span>演示分块数</span></div><div><strong>关键词</strong><span>默认检索路径</span></div></div>
  <section v-if="editor" class="card editor-panel"><div class="section-heading"><h2>{{editing?'编辑':'新增'}}{{names[page]}}</h2><button class="icon-button" aria-label="关闭编辑表单" @click="editor=false"><Icon name="close"/></button></div><form @submit.prevent="submit"><div v-if="error" class="alert-banner danger" role="alert">{{error}}</div><div class="form-grid">
    <template v-if="page==='departments'"><label class="field">科室名称<input v-model="form.name" placeholder="例如：消化内科" required/></label><label class="field">唯一编码<input v-model="form.code" placeholder="例如：DIGEST" required/></label><label class="field">就诊位置<input v-model="form.location" placeholder="门诊楼楼层与区域" required/></label></template>
    <template v-if="page==='doctors'"><label class="field">医生姓名<input v-model="form.name" required/></label><label class="field">归属科室<select v-model.number="form.department_id"><option v-for="d in data.departments" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="field">职称<input v-model="form.title"/></label><label class="field">擅长方向<input v-model="form.specialty"/></label></template>
    <template v-if="page==='schedules'"><label class="field">出诊医生<select v-model.number="form.doctor_id"><option v-for="d in data.doctors" :key="d.id" :value="d.id">{{d.name}} · {{dept(d.department_id)}}</option></select></label><label class="field">就诊日期<input v-model="form.work_date" type="date" :min="day()" required/></label><label class="field">时段<select v-model="form.period"><option value="AM">上午</option><option value="PM">下午</option></select></label><label class="field">总号数<input v-model.number="form.total_num" type="number" min="0" step="1" required/></label></template>
    <template v-if="page==='users'"><label class="field">登录名<input v-model="form.login_name" required autocomplete="off"/></label><label class="field">显示名称<input v-model="form.display_name" required/></label><label class="field">角色<select v-model="form.role"><option value="patient">患者 patient</option><option value="doctor">医生 doctor</option><option value="admin">管理员 admin</option></select></label><label class="field">档案 id<input v-model.number="form.ref_id" type="number" :min="form.role==='admin'?0:1"/></label><label class="field">初始演示口令<input v-model="form.password" type="password" autocomplete="new-password" required/><small class="muted">至少 8 位，包含大小写、数字、符号；不会保存。</small></label></template>
    <template v-if="page==='kb'"><label class="field">唯一文档标题<input v-model="form.title" required/></label><label class="field">分类<select v-model="form.category"><option>就诊指南</option><option>门诊服务</option><option>知识规范</option></select></label><label class="field span-two">正文<textarea v-model="form.body" rows="6" required></textarea></label></template>
  </div><div class="button-row space-top"><button class="button">保存{{names[page]}}</button><button type="button" class="button secondary" @click="editor=false">取消</button></div></form></section>
  <section v-if="resetUser" class="card editor-panel"><h2>重置 {{resetUser.login_name}} 的演示口令</h2><form @submit.prevent="resetPassword"><label class="field">新演示口令<input v-model="newPassword" type="password" autocomplete="new-password"/></label><div class="button-row"><button class="button danger">确认重置</button><button type="button" class="button secondary" @click="resetUser=null;newPassword=''">取消</button></div></form></section>
  <section v-if="kbResults!==null" class="card space-top"><h2>关键词检索结果 · {{kbResults.length}} 条</h2><article v-for="r in kbResults" :key="r.title" class="kb-result"><h3>{{r.title}}</h3><p>{{r.text}}</p></article><div v-if="!kbResults.length" class="empty-state"><Icon name="search" :size="28"/><h3>未找到匹配片段</h3><p>试试“预约”或“呼吸”等关键词。</p></div></section>
  <section class="card table-card"><div class="table-scroll"><table v-if="page==='departments'"><thead><tr><th>科室名称</th><th>编码</th><th>就诊位置</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}}</small></td><td><code>{{r.code}}</code></td><td>{{r.location}}</td><td><span class="badge" :class="{neutral:!r.enabled}">{{r.enabled?'启用':'停用'}}</span></td><td><div class="table-actions"><button @click="openEditor(r)">编辑</button><button @click="toggle(r)">{{r.enabled?'停用':'启用'}}</button><button class="danger-text" @click="remove(r)">删除</button></div></td></tr></tbody></table>
  <table v-else-if="page==='doctors'"><thead><tr><th>医生</th><th>归属科室</th><th>职称 / 擅长</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}}</small></td><td>{{dept(r.department_id)}}</td><td>{{r.title}}<small>{{r.specialty}}</small></td><td><span class="badge" :class="{neutral:!r.enabled}">{{r.enabled?'启用':'停用'}}</span></td><td><div class="table-actions"><button @click="openEditor(r)">编辑</button><button @click="toggle(r)">{{r.enabled?'停用':'启用'}}</button><button class="danger-text" @click="remove(r)">删除</button></div></td></tr></tbody></table>
  <table v-else-if="page==='schedules'"><thead><tr><th>医生 / 科室</th><th>日期</th><th>时段</th><th>总号</th><th>剩余</th><th>状态</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{doctor(r.doctor_id)}}</strong><small>{{dept(r.department_id)}} · #{{r.id}}</small></td><td>{{r.work_date}}</td><td>{{r.period==='AM'?'上午':'下午'}}</td><td>{{r.total_num}}</td><td><strong>{{r.remain_num}}</strong></td><td><span class="badge" :class="{neutral:!r.remain_num}">{{r.remain_num?'有号':'约满'}}</span></td></tr></tbody></table>
  <table v-else-if="page==='users'"><thead><tr><th>登录名</th><th>显示名称</th><th>角色</th><th>档案 id</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><code>{{r.login_name}}</code></td><td>{{r.display_name}}</td><td><span class="badge">{{r.role}}</span></td><td>{{r.ref_id}}</td><td><button class="text-button" @click="resetUser=r;newPassword=''">重置口令</button></td></tr></tbody></table>
  <table v-else><thead><tr><th>文档标题</th><th>分类</th><th>字符数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.title}}</strong><small>#{{r.id}}</small></td><td>{{r.category}}</td><td>{{r.body.length}}</td><td><span class="badge" :class="{neutral:!r.enabled}">{{r.enabled?'启用':'停用'}}</span></td><td><div class="table-actions"><button @click="openEditor(r)">编辑</button><button @click="toggle(r)">{{r.enabled?'停用':'启用'}}</button><button class="danger-text" @click="remove(r)">删除</button></div></td></tr></tbody></table></div><div v-if="!rows.length" class="empty-state"><Icon name="search" :size="32"/><h3>没有匹配记录</h3><p>调整筛选条件，或新增一条演示记录。</p></div><div class="table-footer" data-reading-aid="依据">当前展示 {{rows.length}} 条演示数据 <span>正式接口仅 limit 限额，无真正分页</span></div></section>
</div>
</template>
